import{_ as i,C as o,o as a,c as n,a4 as t,b as l,w as s,a as c,E as d,a5 as p}from"./chunks/framework.BRzJ4ijD.js";const y=JSON.parse('{"title":"Three Pillars (Metrics / Logs / Traces)","description":"","frontmatter":{},"headers":[],"relativePath":"system-design/monitor/pillars.md","filePath":"system-design/monitor/pillars.md","lastUpdated":1788475713000}'),u={name:"system-design/monitor/pillars.md"};function h(g,e,m,b,q,k){const r=o("Mermaid");return a(),n("div",null,[e[1]||(e[1]=t(`<h1 id="three-pillars-metrics-logs-traces" tabindex="-1">Three Pillars (Metrics / Logs / Traces) <a class="header-anchor" href="#three-pillars-metrics-logs-traces" aria-label="Permalink to &quot;Three Pillars (Metrics / Logs / Traces)&quot;">​</a></h1><h2 id="tl-dr" tabindex="-1">TL;DR <a class="header-anchor" href="#tl-dr" aria-label="Permalink to &quot;TL;DR&quot;">​</a></h2><p>可观测性&quot;三大支柱&quot; 是工业界共识的三种信号类型:</p><ol><li><strong>Metrics</strong>: 二进制 numeric time-series data (CPU util, RPS, error rate, latency).prometheus exposition format, aggregation makes efficient (无 per-event record)。</li><li><strong>Logs</strong>: 事件级 records (annotated text/JSON)用于 deep-diagnose. 所有微小事件可查 (debug log) → 节省开销 batch.</li><li><strong>Traces</strong>: 跨 service call path + span timing — 让你看到 request 从 user 到 DB + many microservices 的传递链.</li></ol><p>每类信号有 purpose:</p><ul><li>Metrics: 大尺度状态、告警</li><li>Logs: 单事件诊断</li><li>Traces: 端到端 latency breakdown</li></ul><p>现代 stack: <strong>OpenTelemetry</strong> 统一收集的 formats. 数据 pipeline. 与 alerting via Prometheus/Grafana / Loki / Tempo / Jaeger 组合.</p><p>本章扫每类信号特点 + Trade-offs (cardinality cost), Performance implication (不惜 log per request for 高 throughput), 与防护舆 typical.</p><hr><h2 id="一、metrics" tabindex="-1">一、Metrics <a class="header-anchor" href="#一、metrics" aria-label="Permalink to &quot;一、Metrics&quot;">​</a></h2><h3 id="形式" tabindex="-1">形式 <a class="header-anchor" href="#形式" aria-label="Permalink to &quot;形式&quot;">​</a></h3><p>Metrics 是 &quot;聚合数值时间序列数据&quot; — 每 series 由一组label set 维 identify (e.g., <code>http_requests_total{method=POST, status=200}</code>) 。 Prometheus exposition format 典型:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># HELP http_requests_total Number of HTTP requests</span></span>
<span class="line"><span># TYPE http_requests_total counter</span></span>
<span class="line"><span>http_requests_total{method=&quot;GET&quot;,status=&quot;200&quot;} 124851</span></span>
<span class="line"><span>http_requests_total{method=&quot;POST&quot;,status=&quot;500&quot;} 12</span></span></code></pre></div><h3 id="_4-种-metric-type" tabindex="-1">4 种 metric type <a class="header-anchor" href="#_4-种-metric-type" aria-label="Permalink to &quot;4 种 metric type&quot;">​</a></h3><table tabindex="0"><thead><tr><th>类型</th><th>用途</th></tr></thead><tbody><tr><td><strong>Counter</strong> (单调增): 累计计算 e.g. <code>requests_total</code></td><td></td></tr><tr><td><strong>Gauge</strong> (可增减): 瞬时数 e.g. <code>current_connections</code></td><td></td></tr><tr><td><strong>Histogram</strong> (bucket): latency distribution (P50/P90/P99 大量计算 bucket with retention金: <code>_bucket</code>, <code>_sum</code>, <code>_count</code>)</td><td></td></tr><tr><td><strong>Summary</strong> (客户端 quantile): 客户端 实时 P50/P99 但 unsuited aggregation across instances</td><td></td></tr></tbody></table><h3 id="cardinality-风险" tabindex="-1">Cardinality 风险 <a class="header-anchor" href="#cardinality-风险" aria-label="Permalink to &quot;Cardinality 风险&quot;">​</a></h3><p>Metrics 的 label cardinality — number unique combinations like → memory. Prometheus storage cost near-linear in cardinality over time;</p><ul><li>Label <code>user_id</code> (1M users): 1M 系 Featolder</li><li>Label <code>URL</code> (含<code>:id</code>): 100K URL lines per second → 跨 kill storage</li><li>Label <code>trace_id</code></li></ul><p>Rule of thumb: any label with cardinality &gt; 1000 应 simplif or rollup INCLUDING to avoid explosion.</p><h3 id="prometheus-metric-exposition" tabindex="-1">Prometheus metric exposition <a class="header-anchor" href="#prometheus-metric-exposition" aria-label="Permalink to &quot;Prometheus metric exposition&quot;">​</a></h3><p>每 service ishould expose <code>/metrics</code> endpoint with Prometheus exposition format. Prometheus <strong>scrape</strong> (default 15s). 存储 点向 metrics backends: M3DB, VictoriaMetrics, Cortex, Thanos for scale.</p><hr><h2 id="二、logs" tabindex="-1">二、Logs <a class="header-anchor" href="#二、logs" aria-label="Permalink to &quot;二、Logs&quot;">​</a></h2><h3 id="levels" tabindex="-1">Levels <a class="header-anchor" href="#levels" aria-label="Permalink to &quot;Levels&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>TRACE | DEBUG | INFO | WARN | ERROR | FATAL</span></span></code></pre></div><p>Production 通常 INFO+; DEBUG log 仅在故障时启用 (cross debug 调查). Tools: loom long-term retention + 结构化 logging for searchability.</p><h3 id="structured-vs-unstructured" tabindex="-1">Structured vs Unstructured <a class="header-anchor" href="#structured-vs-unstructured" aria-label="Permalink to &quot;Structured vs Unstructured&quot;">​</a></h3><p><strong>Unstructured</strong>: <code>printf(&quot;Error at file ... &quot;)</code> — 可 grep 但 not machine-parseable.</p><p><strong>Structured</strong> (JSON for tools): <code>{&quot;level&quot;:&quot;error&quot;,&quot;ts&quot;:&quot;...&quot;,&quot;msg&quot;:&quot;checkout&quot;,&quot;user_id&quot;:42, &quot;cart_id&quot;:&quot;abc&quot;}</code> — ELK 加 indexing on fields.</p><h3 id="高-throughput-logging-cost" tabindex="-1">高 throughput logging cost <a class="header-anchor" href="#高-throughput-logging-cost" aria-label="Permalink to &quot;高 throughput logging cost&quot;">​</a></h3><ul><li>企业应单机 1 GB/day log limit easily 2500 USD/month. 推荐sampling.</li><li>&quot;all access logs kept 7 years合法 不首通用 optimizations keep origin proj纳入 access log snapshot + sample tail info 「 金 network cost 持 abog&quot;.</li></ul><h3 id="典型-stack" tabindex="-1">典型 stack <a class="header-anchor" href="#典型-stack" aria-label="Permalink to &quot;典型 stack&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Application</span></span>
<span class="line"><span>  ↓ structured log (JSON / logfmt)</span></span>
<span class="line"><span>Filebeat / Vector / Fluent Bit</span></span>
<span class="line"><span>  ↓ agent obtains</span></span>
<span class="line"><span>Kafka log streams</span></span>
<span class="line"><span>  ↓ async producer backend</span></span>
<span class="line"><span>Loki / Elasticsearch / OpenSearch / ClickHouse / S3</span></span>
<span class="line"><span>  ↓ query</span></span>
<span class="line"><span>Kibana / Grafana</span></span></code></pre></div><h3 id="性能开销" tabindex="-1">性能开销 <a class="header-anchor" href="#性能开销" aria-label="Permalink to &quot;性能开销&quot;">​</a></h3><ul><li>单 INFO log 每 5KB → agent 服务 / 后端 indexing 加序列化 json extra 50-100us.</li><li>高吞吐 log load 会 server process thread pool + disk IO. consider async logger (e.g. log4j 2.x async logger 或 source klog V8 flush).</li></ul><hr><h2 id="三、traces" tabindex="-1">三、Traces <a class="header-anchor" href="#三、traces" aria-label="Permalink to &quot;三、Traces&quot;">​</a></h2><h3 id="opentracing-opentelemetry" tabindex="-1">OpenTracing / OpenTelemetry <a class="header-anchor" href="#opentracing-opentelemetry" aria-label="Permalink to &quot;OpenTracing / OpenTelemetry&quot;">​</a></h3><p>OpenTracing 与 OpenCensus 2019 合并 → OpenTelemetry (OTel)。 提供 language-agnostic API for traces context propagation。 HTTP/gRPC header injection让 trace_id 跨medration services传递.</p><h3 id="span-trace" tabindex="-1">Span / Trace <a class="header-anchor" href="#span-trace" aria-label="Permalink to &quot;Span / Trace&quot;">​</a></h3><ul><li><strong>Trace</strong>: 完整 end-to-end path lifecycle 的 unique trace_id.</li><li><strong>Span</strong>: 一个服务 node的 single sub-process timing + tags.</li><li>父 span → child span; siblings → concurrent calls.</li></ul><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Trace: trace_id=abc, total 800ms</span></span>
<span class="line"><span>  Span1: HTTP /api/checkout, 800ms [parent]</span></span>
<span class="line"><span>    Span2: db.query SELECT order, 50ms [child]</span></span>
<span class="line"><span>    Span3: call shipping service, 200ms [child]</span></span>
<span class="line"><span>       Span4: shipping DB query, 150ms [child]</span></span>
<span class="line"><span>    Span5: redis cache get user, 5ms [child]</span></span>
<span class="line"><span>    Span6: payment service call, 500ms [child]</span></span></code></pre></div><h3 id="distributed-context-propagation" tabindex="-1">Distributed context propagation <a class="header-anchor" href="#distributed-context-propagation" aria-label="Permalink to &quot;Distributed context propagation&quot;">​</a></h3><ul><li>HTTP <code>traceparent</code> header W3C standard format: <code>00-{trace_id}-{span_id}-{flags}</code>.</li><li>OTel auto-instrumentation: agents attach to popular libraries (e.g. JDBC, gRPC, Spring) 自动 emit spans.</li></ul><h3 id="distributed-trace-storage" tabindex="-1">Distributed Trace Storage <a class="header-anchor" href="#distributed-trace-storage" aria-label="Permalink to &quot;Distributed Trace Storage&quot;">​</a></h3><ul><li>Backend: Jaeger / Tempo / OpenSearch / Datadog / Honeycomb / New Relic.</li><li>Sampling 控制 retention cost (e.g., 100% sampling at low流量, 1% at high RPS).</li></ul><h3 id="sampling" tabindex="-1">Sampling <a class="header-anchor" href="#sampling" aria-label="Permalink to &quot;Sampling&quot;">​</a></h3><ul><li>Head sampling: collector 概率性 drop traces before processing. e.g. 1% records.</li><li>Tail sampling: collector 全采集; lifestream 完成后决定保留 (e.g., keep &gt;= P99 latency or error status). resource-limited.</li></ul><hr><h2 id="四、三者关系" tabindex="-1">四、三者关系 <a class="header-anchor" href="#四、三者关系" aria-label="Permalink to &quot;四、三者关系&quot;">​</a></h2>`,50)),(a(),l(p,null,{default:s(()=>[d(r,{id:"mermaid-278",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20A%5BApplication%3Cbr%2F%3Esignals%5D%20--%3E%20M%5BMetrics%3A%20aggregate%5D%0A%20%20%20%20A%20--%3E%20L%5BLogs%3A%20per-event%20records%5D%0A%20%20%20%20A%20--%3E%20T%5BTraces%3A%20span%20breakdown%5D%0A%20%20%20%20M%20--%3E%20P%5BPrometheus%5D%3Cbr%2F%3E%2F%20alerting%0A%20%20%20%20L%20--%3E%20E%5BLoki%20%2F%20Elasticsearch%5D%0A%20%20%20%20T%20--%3E%20J%5BJaeger%20%2F%20Tempo%5D%0A%20%20%20%20P%20--%3E%20G%5BGrafana%20dashboards%5D%0A%20%20%20%20E%20--%3E%20G%0A%20%20%20%20J%20--%3E%20G%0A"})]),fallback:s(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=t(`<ul><li>alerting migrations look for 用 Metrics. -incident 调试从 Logs + Traces = # behavior回到 stack-grained origin. -Traces 给 spans 转 Metrics events, logs 引记录 trace_id扰动 curation 快 lookup.</li></ul><h3 id="exemplars-prometheus-2-26" tabindex="-1">Exemplars (Prometheus 2.26+) <a class="header-anchor" href="#exemplars-prometheus-2-26" aria-label="Permalink to &quot;Exemplars (Prometheus 2.26+)&quot;">​</a></h3><p><strong>Exemplar</strong> = &quot;Metric point + trace_id 引用 &quot;. 让 Grafana 中点 P99 latency 节点 → click → 引言含 trace_id → jump to Jaeger/Tempo看具体 trace. 桥接 metrics与 traces.</p><hr><h2 id="五、典型-architectural-patterns" tabindex="-1">五、典型 Architectural Patterns <a class="header-anchor" href="#五、典型-architectural-patterns" aria-label="Permalink to &quot;五、典型 Architectural Patterns&quot;">​</a></h2><h3 id="pattern-1-service-stack-with-opentelemetry" tabindex="-1">Pattern 1: Service Stack with OpenTelemetry <a class="header-anchor" href="#pattern-1-service-stack-with-opentelemetry" aria-label="Permalink to &quot;Pattern 1: Service Stack with OpenTelemetry&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>App code (OpenTelemetry SDK)</span></span>
<span class="line"><span>  ↓ OTLP / Prometheus</span></span>
<span class="line"><span>[OpenTelemetry Collector] (dep role-forwarding/log累积/data aggregation/sampling)</span></span>
<span class="line"><span>  ↓ forked</span></span>
<span class="line"><span>Prometheus (metrics) | Loki (logs) | Tempo (traces)</span></span>
<span class="line"><span>  ↓</span></span>
<span class="line"><span>Grafana (unified view)</span></span></code></pre></div><h3 id="pattern-2-cloud-native-observability-datadog-honeycomb-new-relic" tabindex="-1">Pattern 2: Cloud Native Observability (Datadog / Honeycomb / New Relic) <a class="header-anchor" href="#pattern-2-cloud-native-observability-datadog-honeycomb-new-relic" aria-label="Permalink to &quot;Pattern 2: Cloud Native Observability (Datadog / Honeycomb / New Relic)&quot;">​</a></h3><p>提供 hosted solution, 多 SDKs (e.g. dd-agent on each pod), agent forwards. Trade-off: high volume cost-per-GB. Vendor lock 注意.</p><h3 id="pattern-3-elk-stack-logs-prometheus-metrics-jaeger-traces" tabindex="-1">Pattern 3: ELK Stack Logs + Prometheus Metrics + Jaeger Traces <a class="header-anchor" href="#pattern-3-elk-stack-logs-prometheus-metrics-jaeger-traces" aria-label="Permalink to &quot;Pattern 3: ELK Stack Logs + Prometheus Metrics + Jaeger Traces&quot;">​</a></h3><p>Self-hosted stack 经典 选择. ELK (现在 &quot;OpenSearch&quot;—fork of ElasticSearch 2021) Logs + Prom Metrics + Jaeger Traces.</p><hr><h2 id="六、典型-use-cases" tabindex="-1">六、典型 Use Cases <a class="header-anchor" href="#六、典型-use-cases" aria-label="Permalink to &quot;六、典型 Use Cases&quot;">​</a></h2><p>###triggerance 1: Diagnose High Latency Report</p><ol><li>Alert: &quot;checkout API P99 latency 5s&quot; 触发 from metrics</li><li>Grafana dashboard 看 P99 derivation of recent checkout success rate</li><li>Exemplar link to specific trace / 导致 Trace ID range.</li><li>Jaeger 看 trace: &quot;shipping service 500ms&quot; + &quot;db query 300ms&quot;.</li><li>Span detail: sql query atement + SQL timings + Service specific span ID.</li><li>logs by trace_id = （SQL plan + Postgres query log）</li><li>resolve query.</li></ol><h3 id="triggerance-2-error-spike-diagnostic" tabindex="-1">Triggerance 2: Error Spike Diagnostic <a class="header-anchor" href="#triggerance-2-error-spike-diagnostic" aria-label="Permalink to &quot;Triggerance 2: Error Spike Diagnostic&quot;">​</a></h3><p>-alerts 监测 error rate metric 是 spike. -Watch战 back dashboard, failed request spans 找;</p><ul><li>Look at logs filtered by <code>status=500</code>; -Restart跑 server app 看行 exception.</li></ul><hr><h2 id="七、典型事故" tabindex="-1">七、典型事故 <a class="header-anchor" href="#七、典型事故" aria-label="Permalink to &quot;七、典型事故&quot;">​</a></h2><h3 id="elasticsearch-cluster-oom-大量-object-high-cardinality" tabindex="-1">Elasticsearch Cluster OOM 大量 Object High Cardinality <a class="header-anchor" href="#elasticsearch-cluster-oom-大量-object-high-cardinality" aria-label="Permalink to &quot;Elasticsearch Cluster OOM 大量 Object High Cardinality&quot;">​</a></h3><p>某公司 ES logstorage 组 tagged with <code>user_id</code> as a field. multi-CO者 ES hop heap 充 ~100GB/天 overwhelmed cluster. Fix: user_id 在 long-term retention 跳 low index + aggregated per user_id 游 实际 lookup.</p><h3 id="datadog-cold-card-trick" tabindex="-1">Datadog Cold-Card Trick <a class="header-anchor" href="#datadog-cold-card-trick" aria-label="Permalink to &quot;Datadog Cold-Card Trick&quot;">​</a></h3><p>某 team通过 trace &quot;every&quot; 学校 DNS error: named 只 100 RPS, but e.g Develop 拒tring count all latency loader data incurred over-time $买 100MB month + DEMos rule 权. Fix:</p><h3 id="loki-cards-decrease-storage-cost" tabindex="-1">Loki cards Decrease storage cost <a class="header-anchor" href="#loki-cards-decrease-storage-cost" aria-label="Permalink to &quot;Loki cards Decrease storage cost&quot;">​</a></h3><p>某公司 Loki query (~10×less cost than ES) for logs, substitution / success.</p><hr><h2 id="八、易错清单" tabindex="-1">八、易错清单 <a class="header-anchor" href="#八、易错清单" aria-label="Permalink to &quot;八、易错清单&quot;">​</a></h2><ol><li><strong>Don&#39;t use <code>user_id</code>, <code>session_id</code>, <code>trace_id</code> as metric label</strong> — cardinality爆炸 storage cost。</li><li><strong>Trace sampling must include all errors</strong>: tail sampling keeps 100% errors + 1% success, 重要性数据采集.</li><li><strong>OpenTelemetry MUST support all service tiers</strong> (HTTP/gRPC/db/cache)</li><li><strong>Set alerting on user-facing metrics, not behind infrastructure-only</strong></li><li><strong>High-cardinality log fields</strong>: avoid to give ś user_id as part of indexed log key.</li><li><strong>Trace 爆炸 over service mesh 重在 hist 纕 keep sample-server-side samples by path.</strong></li></ol><hr><h2 id="九、这一章带走的东西" tabindex="-1">九、这一章带走的东西 <a class="header-anchor" href="#九、这一章带走的东西" aria-label="Permalink to &quot;九、这一章带走的东西&quot;">​</a></h2><ol><li>三大支柱 Metrics + Logs + Traces 是观测分布式系统的 entry point.</li><li>Metrics aggregate- numeric格式上 cost-aware labelsetdecount的 cardinality problematic.</li><li>Logs structured JSON 让 query/filter 不过 cost-per-event 的处理; sampling retains large. febyterianik.</li><li>Traces span breakdown 让 latency decoupled visible; OpenTelemetry sets of standards.</li><li>Exemplars 锵 metrics 与 traces bridges Grafana links point. 6.用 Prometheus + Graphana; Loki or ES for logs; 真Jaeger/Tempo 您 traces distribution. Currently &quot;slotel collector&quot; emerging best 埋持 alternative.</li></ol><hr><p>下一节 → <a href="./slo">SLO/SLI/Error Budget</a></p>`,34))])}const P=i(u,[["render",h]]);export{y as __pageData,P as default};
